  const arTxt = (x, y, t, cls, ancre) => `<text class="${cls || "g-label"}" x="${x}" y="${y}"${ancre ? ` text-anchor="${ancre}"` : ""}>${t}</text>`;
  // Lignes de groupes de a points : L = [{ nom, n (nombre de groupes), deux (groupes surlignés à partir de cet indice) }]
