  FIGURES["dr-cours-directeur"] = () => graph({ xmin: -1.5, xmax: 5.5, ymin: -4.5, ymax: 4.5, curves: [{ f: (x) => 5 - 2 * x, a: -0.2, b: 4.6, closed: false }], fleches: [{ x1: 1, y1: 3, x2: 4, y2: -3, c: 1 }, { x1: 3, y1: 3, x2: 4, y2: 1, c: 1, label: "u" }], points: [{ x: 1, y: 3, label: "A", gauche: true }, { x: 4, y: -3, label: "B" }], aria: "Droite (AB) avec A(1 ; 3) et B(4 ; −3) ; le vecteur AB(3 ; −6) et le vecteur u(1 ; −2), plus court, ont la même direction que la droite" });
