    let a, b, c, k, x0;
    do { a = randNZ(-4, 4); c = rand(-6, 6); k = randNZ(-4, 4); x0 = rand(-6, 6); b = k * (x0 + c) - a * x0; } while (a === k || x0 === -c || Math.abs(b) > 20);
