  // Plaque rectangulaire L × l dont on découpe un carré de côté x à chaque coin (même dessin que patron)
  function syPatron(L, l) {
    const o = 46, Lp = 228, lp = Math.round((Lp * l) / L), x = Math.round(lp * 0.2), H = lp + 44;
    let s = `<svg class="graph" viewBox="0 0 320 ${H}" role="img" aria-label="Plaque de ${L} cm sur ${l} cm dont on découpe un carré de côté x à chaque coin ; le fond mesure ${L} − 2x sur ${l} − 2x">`;
    s += `<rect x="${o}" y="10" width="${Lp}" height="${lp}" style="fill:var(--lagon-pale);stroke:var(--lagon);stroke-width:1.6"/>`;
    [[0, 0], [Lp - x, 0], [0, lp - x], [Lp - x, lp - x]].forEach(([a, b]) => { s += `<rect x="${o + a}" y="${10 + b}" width="${x}" height="${x}" style="fill:var(--surface);stroke:var(--faux);stroke-width:1.4;stroke-dasharray:4 3"/>`; });
    s += `<rect x="${o + x}" y="${10 + x}" width="${Lp - 2 * x}" height="${lp - 2 * x}" style="fill:none;stroke:var(--doux);stroke-width:1;stroke-dasharray:3 3"/>`;
    s += `<text class="g-label" x="${o + x / 2}" y="${10 + x / 2 + 4}" text-anchor="middle">x</text><text class="g-label" x="${o + Lp / 2}" y="${10 + lp / 2 + 4}" text-anchor="middle">fond</text>`;
    s += `<text class="g-label" x="${o + Lp / 2}" y="${lp + 30}" text-anchor="middle">${L} cm</text><text class="g-label" x="${o - 6}" y="${10 + lp / 2 + 4}" text-anchor="end">${l} cm</text>`;
    return s + `</svg>`;
  }

