  const psAngle = { 0: "0", 30: "\\dfrac{\\pi}{6}", 45: "\\dfrac{\\pi}{4}", 60: "\\dfrac{\\pi}{3}", 90: "\\dfrac{\\pi}{2}", 120: "\\dfrac{2\\pi}{3}", 135: "\\dfrac{3\\pi}{4}", 150: "\\dfrac{5\\pi}{6}", 180: "\\pi" };
